const body = $input.first().json.body || {};

const provider = body.provider || 'mimo';
const text = body.text;
const voice = body.voice || '冰糖';
const format = body.format || 'wav';
const instruction = body.instruction || '用自然亲切的语气播报';

if (!text) {
  throw new Error('缺少必填字段: text (配音文本)');
}

const supportedProviders = ['mimo'];
if (!supportedProviders.includes(provider)) {
  throw new Error(`不支持的 provider: ${provider}。当前支持: ${supportedProviders.join(', ')}`);
}

// 构建 Mimo TTS 请求体
const requestBody = {
  model: 'mimo-v2.5-tts',
  messages: [
    { role: 'user', content: instruction },
    { role: 'assistant', content: text }
  ],
  audio: { format: format, voice: voice },
  stream: false
};

return [{ json: requestBody }];

const response = $input.first().json;
const choice = response?.choices?.[0];
const audioData = choice?.message?.audio?.data;

if (!audioData) {
  throw new Error('Mimo TTS 响应异常: ' + JSON.stringify(response).substring(0, 300));
}

const format = choice.message.audio.format || 'wav';

return [{
  json: {
    status: 'success',
    format: format
  },
  binary: {
    data: {
      data: Buffer.from(audioData, 'base64'),
      mimeType: `audio/${format}`,
      fileName: `tts-output.${format}`
    }
  }
}];

const item = $input.first();
const hasBinary = !!(item.binary && item.binary.data);

if (!hasBinary) {
  return [{
    json: {
      success: false,
      error: '音频生成失败',
      provider: 'mimo'
    }
  }];
}

const binaryData = item.binary.data;

return [{
  json: {
    success: true,
    provider: 'mimo',
    model: 'mimo-v2.5-tts',
    fileName: binaryData.fileName || 'tts-output.wav',
    mimeType: binaryData.mimeType || 'audio/wav',
    fileSize: binaryData.fileSize || 0,
    generatedAt: new Date().toISOString()
  },
  binary: { data: binaryData }
}];
